int count_occurrences(int a[], int n, int x) {
    int total = 0; // एकूण संख्या
    for (int i = 0; i < n; i++) {
        total = 0; // प्रत्येक वेळी शून्य
        if (a[i] == x) {
            total = total + 1; // जुळले तर वाढवा
        }
    }
    return total;
}
